import { In, Repository } from 'typeorm';
import { User } from '../entities/User.entity';

export const USER_SELECT_COLUMNS = [
  'user.id',
  'user.email',
  'user.passwordHash',
  'user.fullName',
  'user.role',
  'user.studentCode',
  'user.className',
  'user.identityNumber',
  'user.phone',
  'user.course',
  'user.permanentAddress',
  'user.cardNumber',
  'user.issueDate',
  'user.membershipExpiry',
  'user.status',
  'user.currentStatus',
  'user.lastEntryAt',
  'user.lastEntryCamera',
  'user.createdAt',
  'user.updatedAt',
  'user.passwordAutoGenerated',
  'user.avatarUrl',
  'user.suspendedReason',
  'user.hasFace',
  'user.faceDescriptor',
];

export class UserRepository {
  constructor(protected repo: Repository<User>) {}

  async findById(id: string): Promise<User | null> {
    return this.repo
      .createQueryBuilder('user')
      .select(USER_SELECT_COLUMNS)
      .where('user.id = :id', { id })
      .getOne();
  }

  async findByEmail(email: string): Promise<User | null> {
    return this.repo
      .createQueryBuilder('user')
      .select(USER_SELECT_COLUMNS)
      .where('user.email = :email', { email })
      .getOne();
  }

  async findByIds(ids: string[]): Promise<User[]> {
    if (ids.length === 0) return [];
    return this.repo
      .createQueryBuilder('user')
      .select(USER_SELECT_COLUMNS)
      .where('user.id IN (:...ids)', { ids })
      .getMany();
  }

  async findByStudentCode(code: string): Promise<User | null> {
    return this.repo
      .createQueryBuilder('user')
      .select(USER_SELECT_COLUMNS)
      .where('user.studentCode = :code', { code })
      .getOne();
  }

  async findByCardNumber(card: string): Promise<User | null> {
    return this.repo
      .createQueryBuilder('user')
      .select(USER_SELECT_COLUMNS)
      .where('user.cardNumber = :card', { card })
      .getOne();
  }

  async findAll(skip = 0, limit = 200): Promise<[User[], number]> {
    return this.repo
      .createQueryBuilder('user')
      .select(USER_SELECT_COLUMNS)
      .skip(skip)
      .take(limit)
      .orderBy('user.createdAt', 'DESC')
      .getManyAndCount();
  }

  async findStaff(ids?: string[]): Promise<User[]> {
    const qb = this.repo
      .createQueryBuilder('user')
      .select(USER_SELECT_COLUMNS)
      .where('user.role IN (:...roles)', { roles: ['staff', 'admin'] })
      .andWhere('user.status = :status', { status: 'active' });

    if (ids?.length) {
      qb.andWhere('user.id IN (:...ids)', { ids });
    }

    return qb
      .orderBy('user.fullName', 'ASC')
      .addOrderBy('user.email', 'ASC')
      .getMany();
  }

  async create(data: Partial<User>): Promise<User> {
    const user = this.repo.create(data);
    return this.repo.save(user);
  }

  async update(id: string, data: Partial<User>): Promise<User | null> {
    const result = await this.repo.update(id, data);
    if (result.affected === 0) return null;
    return this.findById(id);
  }

  async delete(id: string): Promise<boolean> {
    const result = await this.repo.delete(id);
    return (result.affected ?? 0) > 0;
  }
}
